const sample = {
  "demo": true,
  "text": "@jonas Send the revised quote.\nDue 2026-12-01.\nAlso update the deck.",
  "source": "meet",
  "channel": "#clients"
};
const incoming = $input.first()?.json ?? {};
const provided = Object.keys(incoming).filter((key) => incoming[key] !== undefined && incoming[key] !== null && incoming[key] !== '');
const base = provided.length ? { ...sample, ...incoming } : { ...sample };
const flag = incoming.demo;
base.demo = !(flag === false || flag === 'false' || flag === 0 || flag === '0');
return [{ json: base }];

const item = $input.first().json;
const produced = (() => {

const text = String(item.text || item.message || '').trim();
const owner = (text.match(/@([a-z0-9._-]+)/i) || [])[1] || item.owner || 'unassigned';
const due = (text.match(/due\s+(\d{4}-\d{2}-\d{2})/i) || [])[1] || item.due || '';
const urgent = /urgent|asap|today|blocker|sev-?1/i.test(text);
const title = text.split('\n')[0].slice(0, 100) || 'Untitled task';
const record = {
  title,
  body: text,
  owner,
  due,
  priority: urgent ? 'high' : 'normal',
  source: item.source || 'slack',
  channel: item.channel || '',
};
return {
  summary: 'Task for ' + owner + (due ? ' due ' + due : '') + ': ' + title,
  route: urgent ? 'urgent' : 'normal',
  record,
  slackText: 'Created a ClickUp task for ' + owner + ': ' + title,
  actions: [{ app: 'ClickUp', operation: 'create task', payload: record }],
};

})();
if (!produced || typeof produced.summary !== 'string' || !produced.summary.trim()) {
  throw new Error('Apply rules must return a summary string');
}
return [{
  json: {
    ...item,
    ...produced,
    demo: item.demo !== false,
  },
}];

const item = $input.first().json;
return [{
  json: {
    demo: true,
    status: 'demo_ready',
    workflow: 'meeting-notes-to-tasks',
    summary: item.summary,
    route: item.route ?? null,
    record: item.record ?? {},
    actions: item.actions ?? [],
    slackText: item.slackText ?? item.summary,
    notes: 'Demo mode did not call external apps. Send {"demo": false} after placeholder credentials are replaced.',
  },
}];
